def get_vertical_order_colors(grid):
    """Get colors in order they appear when scanning top-down, left-right"""
    seen = set()
    order = []
    for r in range(len(grid)):
        row_colors = sorted(set(grid[r][c] for c in range(len(grid[0])) if grid[r][c] not in [0, 4]))
        for color in row_colors:
            if color not in seen:
                order.append(color)
                seen.add(color)
    return order

